const cycle = $input.first().json;
if (typeof cycle.source_execution !== 'string' || !cycle.source_execution.trim() || !Array.isArray(cycle.reports) || !cycle.reports.length) {
  throw new Error('A stable parent execution identity and compiled reports are required.');
}
const delivery = { source_execution: cycle.source_execution, reports: cycle.reports };
if (JSON.stringify(delivery).length > 200000) throw new Error('Cycle exceeds delivery size limit.');
return [{ json: delivery }];

const cycle = $('Prepare delivery').first().json;
const receipt = $input.first().json;
if (receipt.status !== 'received' || !receipt.cycle_id) throw new Error('Mission Control did not acknowledge delivery.');
const successful = cycle.reports.filter(report => report.status === 'completed').length;
if (!successful) throw new Error('HALO agent cycle failed. Failure reports were saved in Mission Control. Check upstream quota, credentials, and response validation.');
return [{ json: { ...receipt, status: successful === cycle.reports.length ? 'completed' : 'partial', successful_agents: successful, total_agents: cycle.reports.length } }];
